mkdir -p /tmp/work && cat > /tmp/work/load.py <<'EOF'
import csv, json, glob
from collections import defaultdict, Counter
A='/app/'
def rd(f): return list(csv.DictReader(open(A+f)))
plan={r['run_id']:r for r in rd('plan.csv')}
launch=rd('launch_log.csv')
L={}
for r in launch:
    L.setdefault(r['run_id'],[]).append(r)
launched=set(L)
ev={}
for r in rd('eval_results.csv'):
    assert r['run_id'] not in ev; ev[r['run_id']]=float(r['pass_rate'])
rt={r['run_id']:r['finished_at'] for r in rd('runtime.csv')}
ret={}
for r in rd('retention_log.csv'):
    assert r['run_id'] not in ret; ret[r['run_id']]=r
shard={}
for f in sorted(glob.glob(A+'recovered/*.csv')):
    for r in rd('recovered/'+f.split('/')[-1]):
        v=float(r['pass_rate_pct'])/100
        if r['run_id'] in shard: assert abs(shard[r['run_id']]-v)<1e-9,(r,shard[r['run_id']])
        shard[r['run_id']]=v
digest={r['date']:(int(r['n_runs']),float(r['sum_pass_rate'])) for r in rd('daily_digest.csv')}
suites=json.load(open(A+'suites.json'))
policy=json.load(open(A+'retention_policy.json'))
reclog=rd('recovery_log.csv')
def floor_at(t):
    for v in policy['versions']:
        if v['from']<=t<v['to']: return v['floor']
    return None
def cat(rid):
    """classify a launched run"""
    s=L[rid][0]; st=s['started_at']; w=s['worker']; fin=rt.get(rid)
    c=[]
    if rid in ev: c.append('eval')
    if rid in shard: c.append('shard')
    if rid in ret: c.append(ret[rid]['reason'])
    if w in('w03','w07') and '2026-06-27T00:00:00Z'<=st<'2026-07-03T12:00:00Z': c.append('INC4471')
    if w=='w09' and '2026-07-11T00:00:00Z'<=st<'2026-07-15T00:00:00Z': c.append('INC4530')
    return tuple(c)
EOF
cd /tmp/work && python3 -c "
from load import *
print('launched',len(launched),'plan',len(plan),'launch rows',len(launch),'ev',len(ev),'rt',len(rt),'ret',len(ret),'shard',len(shard))
print('launched not in plan', launched-set(plan)); print('ev not launched', set(ev)-launched); print('shard not launched', len(set(shard)-launched)); print('rt vs launched', set(rt)^launched)
# multi rows in launch: consistent?
for k,v in L.items():
    if len(v)>1 and len({(x['started_at'],x['worker']) for x in v})>1: print('inconsistent',k,v)
C=Counter(cat(r) for r in launched)
for k,v in sorted(C.items(),key=lambda x:-x[1]): print(v,k)
print('workers',Counter(r['worker'] for r in launch))
print('start range',min(r['started_at'] for r in launch),max(r['started_at'] for r in launch))
"
